// Simple SQL migration runner for MSSQL.
//
// Applies every *.sql file directly under migrations/ (not migrations/tables/,
// which holds full CREATE TABLE dumps generated by generate:tables, not
// incremental migrations) that isn't yet recorded in the SchemaMigrations
// tracking table, in filename order.
//
// Usage:
//   node scripts/migrate.js            apply pending migrations
//   node scripts/migrate.js --baseline mark all current migrations as applied
//                                       without running them (for adopting
//                                       this runner in an environment where
//                                       the .sql files were already applied
//                                       by hand)
const fs = require('fs');
const path = require('path');
const db = require('../database');

const migrationsDir = path.join(__dirname, '..', 'migrations');

async function ensureTrackingTable(pool) {
    await pool.request().query(`
        IF NOT EXISTS (SELECT 1 FROM sys.tables WHERE name = 'SchemaMigrations')
        BEGIN
            CREATE TABLE SchemaMigrations (
                filename NVARCHAR(255) NOT NULL PRIMARY KEY,
                appliedAt DATETIME NOT NULL DEFAULT GETDATE()
            );
        END
    `);
}

function listMigrationFiles() {
    return fs
        .readdirSync(migrationsDir, { withFileTypes: true })
        .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
        .map((entry) => entry.name)
        .sort();
}

async function getAppliedFilenames(pool) {
    const result = await pool.request().query('SELECT filename FROM SchemaMigrations');
    return new Set(result.recordset.map((row) => row.filename));
}

async function runMigrationFile(pool, filename) {
    const sqlScript = fs.readFileSync(path.join(migrationsDir, filename), 'utf8');
    const batches = sqlScript
        .split(/^\s*GO\s*$/im)
        .map((batch) => batch.trim())
        .filter((batch) => batch.length > 0);

    for (const batch of batches) {
        await pool.request().query(batch);
    }
}

async function main() {
    const baseline = process.argv.includes('--baseline');
    const pool = await db.poolPromise;

    await ensureTrackingTable(pool);
    const applied = await getAppliedFilenames(pool);
    const pending = listMigrationFiles().filter((filename) => !applied.has(filename));

    if (pending.length === 0) {
        console.log('Tidak ada migrasi baru.');
        process.exit(0);
    }

    for (const filename of pending) {
        if (baseline) {
            console.log(`Baseline (skip eksekusi): ${filename}`);
        } else {
            console.log(`Menjalankan migrasi: ${filename}`);
            await runMigrationFile(pool, filename);
        }
        await pool
            .request()
            .input('filename', db.sql.NVarChar, filename)
            .query('INSERT INTO SchemaMigrations (filename) VALUES (@filename)');
    }

    console.log(`Selesai. ${pending.length} migrasi ${baseline ? 'ditandai sebagai sudah diterapkan' : 'dijalankan'}.`);
    process.exit(0);
}

main().catch((err) => {
    console.error('Migrasi gagal:', err.message);
    console.error(err);
    process.exit(1);
});
